import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第七章 相邻关系","description":"","frontmatter":{"title":"第七章 相邻关系","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/dierfenbian：suoyouquan（diqizhang：xianglinguanxi）.md","filePath":"blogs/CC/第二分编：所有权（第七章：相邻关系）.md"}'),o={name:"blogs/CC/dierfenbian：suoyouquan（diqizhang：xianglinguanxi）.md"};function n(l,a,h,d,s,_){return t(),r("div",null,[...a[0]||(a[0]=[i('<h3 id="第二百八十八条" tabindex="-1">第二百八十八条 <a class="header-anchor" href="#第二百八十八条" aria-label="Permalink to &quot;第二百八十八条&quot;">​</a></h3><p>不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。</p><h3 id="第二百八十九条" tabindex="-1">第二百八十九条 <a class="header-anchor" href="#第二百八十九条" aria-label="Permalink to &quot;第二百八十九条&quot;">​</a></h3><p>法律、法规对处理相邻关系有规定的，依照其规定；法律、法规没有规定的，可以按照当地习惯。</p><h3 id="第二百九十条" tabindex="-1">第二百九十条 <a class="header-anchor" href="#第二百九十条" aria-label="Permalink to &quot;第二百九十条&quot;">​</a></h3><p>不动产权利人应当为相邻权利人用水、排水提供必要的便利。 对自然流水的利用，应当在不动产的相邻权利人之间合理分配。对自然流水的排放，应当尊重自然流向。</p><h3 id="第二百九十一条" tabindex="-1">第二百九十一条 <a class="header-anchor" href="#第二百九十一条" aria-label="Permalink to &quot;第二百九十一条&quot;">​</a></h3><p>不动产权利人对相邻权利人因通行等必须利用其土地的，应当提供必要的便利。</p><h3 id="第二百九十二条" tabindex="-1">第二百九十二条 <a class="header-anchor" href="#第二百九十二条" aria-label="Permalink to &quot;第二百九十二条&quot;">​</a></h3><p>不动产权利人因建造、修缮建筑物以及铺设电线、电缆、水管、暖气和燃气管线等必须利用相邻土地、建筑物的，该土地、建筑物的权利人应当提供必要的便利。</p><h3 id="第二百九十三条" tabindex="-1">第二百九十三条 <a class="header-anchor" href="#第二百九十三条" aria-label="Permalink to &quot;第二百九十三条&quot;">​</a></h3><p>建造建筑物，不得违反国家有关工程建设标准，不得妨碍相邻建筑物的通风、采光和日照。</p><h3 id="第二百九十四条" tabindex="-1">第二百九十四条 <a class="header-anchor" href="#第二百九十四条" aria-label="Permalink to &quot;第二百九十四条&quot;">​</a></h3><p>不动产权利人不得违反国家规定弃置固体废物，排放大气污染物、水污染物、土壤污染物、噪声、光辐射、电磁辐射等有害物质。</p><h3 id="第二百九十五条" tabindex="-1">第二百九十五条 <a class="header-anchor" href="#第二百九十五条" aria-label="Permalink to &quot;第二百九十五条&quot;">​</a></h3><p>不动产权利人挖掘土地、建造建筑物、铺设管线以及安装设备等，不得危及相邻不动产的安全。</p><h3 id="第二百九十六条" tabindex="-1">第二百九十六条 <a class="header-anchor" href="#第二百九十六条" aria-label="Permalink to &quot;第二百九十六条&quot;">​</a></h3><p>不动产权利人因用水、排水、通行、铺设管线等利用相邻不动产的，应当尽量避免对相邻的不动产权利人造成损害。</p>',18)])])}const p=e(o,[["render",n]]);export{u as __pageData,p as default};
